class Solution:
  def largestPalindrome(self, n: int) -> int:
    if n == 1:
      return 9

    MOD = 1337
    upper = pow(10, n) - 1
    lower = pow(10, n - 1) - 1

    for i in range(upper, lower, -1):
      cand = int(str(i) + str(i)[::-1])
      j = upper
      while j * j >= cand:
        if cand % j == 0:
          return cand % MOD
        j -= 1

