class Solution:
  def sumOfFlooredPairs(self, nums: list[int]) -> int:
    MOD = 1_000_000_007
    MAX = max(nums)
    ans = 0
    count = [0] * (MAX + 1)

    for num in nums:
      count[num] += 1

    for i in range(1, MAX + 1):
      count[i] += count[i - 1]

    for i in range(1, MAX + 1):
      if count[i] > count[i - 1]:
        summ = 0
        j = 1
        while i * j <= MAX:
          lo = i * j - 1
          hi = i * (j + 1) - 1
          summ += (count[min(hi, MAX)] - count[lo]) * j
          j += 1
        ans += summ * (count[i] - count[i - 1])
        ans %= MOD

    return ans

