class Solution:
  def mergeNodes(self, head: ListNode | None) -> ListNode | None:
    if not head:
      return None
    if not head.next.val:
      node = ListNode(head.val)
      node.next = self.mergeNodes(head.next.next)
      return node

    next = self.mergeNodes(head.next)
    next.val += head.val
    return next

class Solution:
  def mergeNodes(self, head: ListNode | None) -> ListNode | None:
    curr = head.next

    while curr:
      running = curr
      summ = 0
      while running.val > 0:
        summ += running.val
        running = running.next

      curr.val = summ
      curr.next = running.next
      curr = running.next

    return head.next

