class Solution:
  def doubleIt(self, head: ListNode | None) -> ListNode | None:
    def getCarry(node: ListNode | None) -> ListNode | None:
      val = node.val * 2
      if node.next:
        val += getCarry(node.next)
      node.val = val % 10
      return val // 10

    if getCarry(head) == 1:
      return ListNode(1, head)
    return head

class Solution:
  def doubleIt(self, head: ListNode | None) -> ListNode | None:
    if head.val >= 5:
      head = ListNode(0, head)

    curr = head

    while curr:
      curr.val *= 2
      curr.val %= 10
      if curr.next and curr.next.val >= 5:
        curr.val += 1
      curr = curr.next

    return head

